/// Maps a 26.3 block id onto `version`.
#[must_use]
pub fn block_id_for_version(id: u16, version: JavaMinecraftVersion) -> Option<u16> {
    let table = match version {
        JavaMinecraftVersion::V_1_16_2
        | JavaMinecraftVersion::V_1_16_3
        | JavaMinecraftVersion::V_1_16_4 => BLOCK_ID_V_1_16_2,
        JavaMinecraftVersion::V_1_17
        | JavaMinecraftVersion::V_1_17_1
        | JavaMinecraftVersion::V_1_18
        | JavaMinecraftVersion::V_1_18_2 => BLOCK_ID_V_1_17,
        JavaMinecraftVersion::V_1_19 | JavaMinecraftVersion::V_1_19_1 => BLOCK_ID_V_1_19,
        JavaMinecraftVersion::V_1_19_3 => BLOCK_ID_V_1_19_3,
        JavaMinecraftVersion::V_1_19_4 => BLOCK_ID_V_1_19_4,
        JavaMinecraftVersion::V_1_20 | JavaMinecraftVersion::V_1_20_2 => BLOCK_ID_V_1_20,
        JavaMinecraftVersion::V_1_20_3 => BLOCK_ID_V_1_20_3,
        JavaMinecraftVersion::V_1_20_5 | JavaMinecraftVersion::V_1_21 => BLOCK_ID_V_1_20_5,
        JavaMinecraftVersion::V_1_21_2 => BLOCK_ID_V_1_21_2,
        JavaMinecraftVersion::V_1_21_4 => BLOCK_ID_V_1_21_4,
        JavaMinecraftVersion::V_1_21_5 => BLOCK_ID_V_1_21_5,
        JavaMinecraftVersion::V_1_21_6 | JavaMinecraftVersion::V_1_21_7 => BLOCK_ID_V_1_21_6,
        JavaMinecraftVersion::V_1_21_9 | JavaMinecraftVersion::V_1_21_11 => BLOCK_ID_V_1_21_9,
        JavaMinecraftVersion::V_26_1 => BLOCK_ID_V_26_1,
        JavaMinecraftVersion::V_26_2 => BLOCK_ID_V_26_2,
        _ => return Some(id),
    };
    table.get(usize::from(id)).copied().flatten()
}

