/// Maps a 26.3 item id onto `version`.
#[must_use]
pub fn item_id_for_version(id: u16, version: JavaMinecraftVersion) -> Option<u16> {
    let table = match version {
        JavaMinecraftVersion::V_1_16_2
        | JavaMinecraftVersion::V_1_16_3
        | JavaMinecraftVersion::V_1_16_4 => ITEM_ID_V_1_16_2,
        JavaMinecraftVersion::V_1_17 | JavaMinecraftVersion::V_1_17_1 => ITEM_ID_V_1_17,
        JavaMinecraftVersion::V_1_18 | JavaMinecraftVersion::V_1_18_2 => ITEM_ID_V_1_18,
        JavaMinecraftVersion::V_1_19 | JavaMinecraftVersion::V_1_19_1 => ITEM_ID_V_1_19,
        JavaMinecraftVersion::V_1_19_3 => ITEM_ID_V_1_19_3,
        JavaMinecraftVersion::V_1_19_4 => ITEM_ID_V_1_19_4,
        JavaMinecraftVersion::V_1_20 | JavaMinecraftVersion::V_1_20_2 => ITEM_ID_V_1_20,
        JavaMinecraftVersion::V_1_20_3 => ITEM_ID_V_1_20_3,
        JavaMinecraftVersion::V_1_20_5 => ITEM_ID_V_1_20_5,
        JavaMinecraftVersion::V_1_21 => ITEM_ID_V_1_21,
        JavaMinecraftVersion::V_1_21_2 => ITEM_ID_V_1_21_2,
        JavaMinecraftVersion::V_1_21_4 => ITEM_ID_V_1_21_4,
        JavaMinecraftVersion::V_1_21_5 => ITEM_ID_V_1_21_5,
        JavaMinecraftVersion::V_1_21_6 => ITEM_ID_V_1_21_6,
        JavaMinecraftVersion::V_1_21_7 => ITEM_ID_V_1_21_7,
        JavaMinecraftVersion::V_1_21_9 => ITEM_ID_V_1_21_9,
        JavaMinecraftVersion::V_1_21_11 => ITEM_ID_V_1_21_11,
        JavaMinecraftVersion::V_26_1 => ITEM_ID_V_26_1,
        JavaMinecraftVersion::V_26_2 => ITEM_ID_V_26_2,
        _ => return Some(id),
    };
    table.get(usize::from(id)).copied().flatten()
}

